# build artifacts / OS junk
sim/*.vvp
sim/iverilog.log
*:Zone.Identifier
# SymbiYosys per-run status dirs (workdirs already ignored above)
formal/i3c_pkg/
formal/i3c_sda_mux/
formal/i3c_regfile/
formal/i3c_bus_frontend/
formal/i3c_bit_engine/
formal/i3c_framer/
formal/i3c_hdr_exit_detector/
formal/i3c_fifo/
formal/i3c_protocol_fsm/
formal/i3c_daa/
formal/i3c_ccc/
formal/i3c_ibi/
formal/i3c_error_recovery/
formal/i3c_avalon_mm/
formal/i3c_integration/
# reports/ holds committed build EVIDENCE ΓÇö keep its logs despite the *.log rule
!reports/*.log
!reports/quartus/*.log
# MIPI I3C spec PDF ΓÇö not redistributed (obtain from mipi.org); keep out of the repo
MIPI-I3C-Basic-Specification-v1-2-public-edition-er01.pdf
*.pdf

# mcy per-module workdirs (regenerated by formal/mcy/gen.sh / campaign.sh)
formal/mcy/i3c_*/
