mkdir -p rtl/lattice syn/lattice/reports
python - <<'EOF'
p='rtl/i3c_target_top.sv'
s=open(p,newline='').read()
nl='\r\n' if '\r\n' in s else '\n'
old="  i3c_io_altera u_io ("
new=nl.join([
"  // Vendor IO shim selection. All shims share one port list and drive model;",
"  // a build picks its own with +define+I3C_IO_SHIM=<module> (e.g. i3c_io_lattice).",
"  // Default is the original Altera shim, so existing flows are unchanged.",
"`ifndef I3C_IO_SHIM",
"  `define I3C_IO_SHIM i3c_io_altera",
"`endif",
"  `I3C_IO_SHIM u_io ("])
assert s.count(old)==1
open(p,'w',newline='').write(s.replace(old,new))
EOF
git diff --stat
cat > rtl/lattice/i3c_io_lattice.sv <<'EOF'
// ============================================================================
// i3c_io_lattice.sv  -  Thin tri-state IO wrapper for Lattice Nexus devices
//                       (Certus-NX / CrossLink-NX / CertusPro-NX / MachXO5-NX)
//
// Drop-in counterpart of rtl/altera/i3c_io_altera.sv: identical port list and
// identical drive semantics. Selected at build time with
//   +define+I3C_IO_SHIM=i3c_io_lattice      (see i3c_target_top.sv)
//
//   - SDA is bidirectional: drive Low / drive High (push-pull) / release (Hi-Z).
//   - SCL is INPUT ONLY: the Target never drives SCL (S1 / R-DRV-02/03).
//
// Drive model (docs/design_decisions.md ┬º3):
//   sda_oe=1, sda_o=0 -> drive Low   (ACK / open-drain 0)
//   sda_oe=1, sda_o=1 -> drive High  (push-pull 1; only in push-pull phases)
//   sda_oe=0          -> release to Hi-Z (external pull-up / bus high-keeper -> 1)
//
// Why an INFERRED tri-state rather than explicit BB / IB primitives:
//   * Both Radiant synthesis engines (Synplify Pro and LSE) map a top-level
//     `assign pad = oe ? o : 1'bz` on an inout port to the Nexus bidirectional
//     buffer BB (I=sda_o, T=~sda_oe, O=sda_i) and a plain input port to IB, so
//     the netlist is the same as a hand-instantiated one. The build confirms
//     this: see the IO section of syn/lattice/reports/i3c_target_impl_1.mrp.
//   * It keeps this file plain SystemVerilog: it simulates in Icarus, Questa
//     and the formal flow without the Lattice primitive libraries (an explicit
//     BB would need lfd2nx/ovi_lfd2nx and a GSR instance in every testbench).
//   * Pad electricals (IO_TYPE, OPENDRAIN, PULLMODE, SLEWRATE, DRIVE) are set
//     where they belong for Nexus, on the port in the .pdc
//     (ldc_set_port -iobuf {...} [get_ports SDA]), not in RTL.
//   To force the primitive anyway, replace the two SDA assigns with
//     BB u_sda (.I(sda_o), .T(~sda_oe), .O(sda_i), .B(SDA));
//     IB u_scl (.I(SCL), .O(scl_i));
//   The port list and semantics are unchanged.
//
// Note: I3C needs BOTH open-drain and push-pull drive on the same pad, so the
// pad must NOT be configured OPENDRAIN=ON; open-drain phases are produced by
// the core only ever asserting sda_oe with sda_o=0 in those phases.
// ============================================================================
`ifndef I3C_IO_LATTICE_SV
`define I3C_IO_LATTICE_SV

module i3c_io_lattice (
  // device-agnostic core side
  input  logic sda_oe,   // 1 = drive, 0 = release
  input  logic sda_o,    // value to drive when sda_oe=1
  output logic sda_i,    // sampled SDA
  output logic scl_i,    // sampled SCL
  // physical pads
  inout  wire  SDA,
  input  wire  SCL
);

  // Bidirectional SDA: drive when enabled, else high-Z (pull-up resolves High).
  assign SDA   = sda_oe ? sda_o : 1'bz;
  assign sda_i = SDA;

  // SCL is input only - the Target has no SCL driver (S1).
  assign scl_i = SCL;

endmodule
`endif
EOF
cat > syn/lattice/i3c_target.sdc <<'EOF'
# =============================================================================
# i3c_target.sdc  -  Timing constraints for the I3C Target on Lattice Radiant
#
# Radiant counterpart of syn/altera/i3c_target.sdc: same clock, same cuts, same
# Avalon-MM I/O budgets. Differences from the Altera file are tool syntax only:
#   * no derive_clock_uncertainty (Quartus-only command)
#   * no `get_ports -nowarn`, no Tcl variables, no all_registers: port lists are
#     written out so both Synplify Pro and the Radiant timing engine accept them
#
# Targets the default build (AVL_ASYNC=0): the top ties avl_clk to sys_clk, so
# ALL logic, including the Avalon-MM interface, is clocked by `clk`, and the
# avl_clk/avl_rst_n pins drive nothing.
#
# sys_clk must be >= 100 MHz (design_decisions D-1); closed here at 125 MHz (8.0 ns).
# =============================================================================

create_clock -name clk -period 8.000 [get_ports clk]

# -----------------------------------------------------------------------------
# Asynchronous I3C bus pads (SDA/SCL go through the 2-3 FF synchronizers;
# metastability closed structurally, not by STA) and the SDA output.
# -----------------------------------------------------------------------------
set_false_path -from [get_ports {SCL SDA}]
set_false_path -to   [get_ports {SDA}]

# Asynchronous reset, de-assertion synchronized internally.
set_false_path -from [get_ports {rst_n}]

# -----------------------------------------------------------------------------
# Avalon-MM application interface (clk domain in the default AVL_ASYNC=0 build).
# Placeholder I/O budgets, identical to the Altera SDC; set to the real
# master/board numbers for sign-off.
# -----------------------------------------------------------------------------
set_input_delay  -clock [get_clocks clk] -max 1.0 [get_ports {avs_address[*] avs_read avs_write avs_writedata[*] avs_byteenable[*]}]
set_input_delay  -clock [get_clocks clk] -min 0.3 [get_ports {avs_address[*] avs_read avs_write avs_writedata[*] avs_byteenable[*]}]
set_output_delay -clock [get_clocks clk] -max 1.0 [get_ports {avs_readdata[*] avs_readdatavalid avs_waitrequest irq}]
set_output_delay -clock [get_clocks clk] -min 0.3 [get_ports {avs_readdata[*] avs_readdatavalid avs_waitrequest irq}]
EOF
cat > syn/lattice/build.tcl <<'EOF'
# =============================================================================
# build.tcl  -  Lattice Radiant project flow for the I3C Target (Certus-NX)
#
#   radiantc syn/lattice/build.tcl        (or pnmainc; run from anywhere)
#
